class Campaign:
    def __init__(self, name):
        self.name = name

    def label(self):
        return self.name.upper()


class EmailCampaign(Campaign):
    def label(self):
        return "EMAIL " + super().label()


c = EmailCampaign("promo")
print(c.label())

