function Counter() {
  const [count, setCount] = useState(0);
  return (
    <button onClick={() => setCount(count + 1)}>
      {count}
    </button>
  );
}

function discount(price: number, rate: number): number {
  return price * (1 - rate);
}

discount("100", 0.2);
